(function execute(inputs, outputs) {
    var userName  = (inputs.username || '').trim();
    var firstName = (inputs.first_name || '').trim();
    var lastName  = (inputs.last_name || '').trim();
    var userPass  = (inputs.password || '').trim();
    var userEmail = (inputs.email || '').trim();
    var regSysId  = (inputs.registration_sys_id || '').trim();

    // 1. Validate mandatory inputs
    if (!userName || !userPass) {
        gs.error("[User Action] FAILED: Missing username or password.");
        outputs.status = "Failed";
        return;
    }

    var grUser = new GlideRecord('sys_user');

    // 2. Check if user already exists in sys_user
    if (grUser.get('user_name', userName)) {
        // UPDATE Existing User
        grUser.setValue('first_name', firstName);
        grUser.setValue('last_name', lastName);
        grUser.setValue('email', userEmail);
        grUser.setValue('user_password', userPass);
        grUser.setValue('active', true);
        grUser.update();
        gs.info("[User Action] Updated existing user: " + userName);

        // Update custom table status to Completed
        if (regSysId) {
            updateCustomRecordStatus(regSysId, 'Completed');
        }
    } else {
        // INSERT New User
        grUser.initialize();
        grUser.setValue('user_name', userName);
        grUser.setValue('first_name', firstName);
        grUser.setValue('last_name', lastName);
        grUser.setValue('email', userEmail);
        grUser.setValue('user_password', userPass);
        grUser.setValue('active', true);

        var newSysId = grUser.insert();

        // 3. Only change status to Completed if sys_user record creation succeeded
        if (newSysId) {
            gs.info("[User Action] Successfully created new user in sys_user: " + newSysId);
            
            if (regSysId) {
                updateCustomRecordStatus(regSysId, 'Completed');
            }
        } else {
            gs.error("[User Action] FAILED to insert user into sys_user: " + grUser.getLastErrorMessage());
            outputs.status = "Failed";
            return;
        }
    }

    outputs.status = "Success";

    // Helper function to update the custom registration record status
    function updateCustomRecordStatus(sysId, statusValue) {
        var regGr = new GlideRecord('x_travel_buddy_app_user_password_registration');
        if (regGr.get(sysId)) {
            regGr.setValue('status', statusValue);
            regGr.update();
            gs.info("[User Action] Custom registration record status changed to: " + statusValue);
        } else {
            gs.error("[User Action] Could not find custom registration record with Sys ID: " + sysId);
        }
    }
})(inputs, outputs);

